"""Programmatic scorers: cheap, deterministic checks. Each returns (passed, reason)."""
import json


def includes(output, groups):
    """Every group of alternatives needs at least one match, ignoring case."""
    text = output.lower()
    missing = [g for g in groups if not any(alt.lower() in text for alt in g)]
    if missing:
        return False, "missing: " + "; ".join(" / ".join(g) for g in missing)
    return True, "all required facts present"


def excludes(output, phrases):
    text = output.lower()
    found = [p for p in phrases if p.lower() in text]
    return (False, "forbidden: " + ", ".join(found)) if found else (True, "nothing forbidden")


def json_matches(output, expected):
    try:
        data = json.loads(output)
    except json.JSONDecodeError as err:
        return False, f"not valid JSON ({err.msg})"
    if not isinstance(data, dict) or set(data) != set(expected):
        return False, f"wrong keys: {sorted(data) if isinstance(data, dict) else type(data).__name__}"
    wrong = {k: data[k] for k in expected if data[k] != expected[k]}
    return (False, f"wrong values: {wrong}") if wrong else (True, "expected JSON")


def score_case(case, output):
    """Run every check the case asks for; the case passes only if all of them pass."""
    checks = {}
    if case.get("must_include"):
        checks["includes"] = includes(output, case["must_include"])
    if case.get("must_not_include"):
        checks["excludes"] = excludes(output, case["must_not_include"])
    if "expected_json" in case:
        checks["json"] = json_matches(output, case["expected_json"])
    return all(ok for ok, _ in checks.values()), checks

"""One interface for three ways of answering: Claude (live), a fake that answers from the recorded
outputs, and a cassette that records answers once and replays them in tests."""
import hashlib
import json
import os
from pathlib import Path


def render(prompt_version, question, policy):
    """Build the exact request for one question. Everything that can change the answer is in here."""
    template = Path(f"prompts/{prompt_version}.txt").read_text()
    return {"system": template.format(policy=policy), "max_tokens": 4096,
            "messages": [{"role": "user", "content": question}]}


class ClaudeLLM:
    def __init__(self):
        import anthropic
        self.client = anthropic.Anthropic()           # reads ANTHROPIC_API_KEY
        self.model = os.environ["CLAUDE_MODEL"]       # a current model ID from docs.anthropic.com

    def answer(self, request):
        response = self.client.messages.create(model=self.model, **request)
        text = "".join(b.text for b in response.content if b.type == "text")
        return {"text": text, "stop_reason": response.stop_reason,
                "usage": {"input_tokens": response.usage.input_tokens,
                          "output_tokens": response.usage.output_tokens}}


class FakeLLM:
    """Answers each golden question with the course's recorded output. No network, no cost."""
    model = "fake-llm-1"

    def __init__(self, outputs_path="outputs_v2.jsonl", golden_path="golden.jsonl"):
        by_id = {json.loads(l)["id"]: json.loads(l)["output"] for l in open(outputs_path) if l.strip()}
        self.by_question = {json.loads(l)["input"]: by_id[json.loads(l)["id"]] for l in open(golden_path) if l.strip()}

    def answer(self, request):
        text = self.by_question[request["messages"][-1]["content"]]
        return {"text": text, "stop_reason": "end_turn", "usage": {"input_tokens": 0, "output_tokens": 0}}


class Cassette:
    """Record answers keyed by a hash of the model and the full request; replay them later."""

    def __init__(self, path, model, recorder=None):
        self.path, self.model, self.recorder = Path(path), model, recorder
        self.entries = json.loads(self.path.read_text()) if self.path.exists() else {}

    def key(self, request):
        return hashlib.sha256(json.dumps({"model": self.model, **request}, sort_keys=True).encode()).hexdigest()[:16]

    def answer(self, request):
        k = self.key(request)
        if k not in self.entries:
            if self.recorder is None:
                raise KeyError(f"no recording for request {k}; the prompt or model changed, so record again")
            self.entries[k] = {"model": self.model, **self.recorder.answer(request)}
            self.path.parent.mkdir(exist_ok=True)
            self.path.write_text(json.dumps(self.entries, indent=1, sort_keys=True))
        return self.entries[k]

